mapper.select:
SELECT * FROM (
  SELECT p.prj_id,p.prj_no,p.prj_nm,c.ptnr_nm AS "custName",p.cntrct_ty_cd,p.cntrct_bgn_dt,
    coalesce(p.cur_end_dt,p.cntrct_end_dt) AS cur_end_dt,p.cur_cntrct_amt,,
    p.bsn_part_id,CASE WHEN p.cntrct_ty_cd='IN' THEN '없음' WHEN b.hq_yn='Y' THEN '본사(직접 영업)' WHEN b.bsn_part_id IS NULL THEN '미지정' ELSE b.bsn_part_nm END AS "partName",p.prj_stts_cd

  WHERE p.use_yn='Y' AND coalesce(p.prfm_bgn_dt,p.cntrct_bgn_dt) <= #{yearEnd} AND coalesce(p.cur_end_dt,p.cntrct_end_dt) >= #{yearStart}
  AND p.cntrct_ty_cd=#{type}
  AND p.prj_stts_cd=#{status}AND p.prj_stts_cd NOT IN ('END','LOST')
  AND p.cntrct_ty_cd!='IN' AND p.bsn_part_id IS NULL
  AND p.bsn_part_id=#{partId}
  AND (position(lower(#{q}) in lower(p.prj_nm))>0 OR position(lower(#{q}) in lower(c.ptnr_nm))>0)
) rows ORDER BY ${order}
